  "onboarding.hotkeyBody": "Press {key} to show or hide the popover from anywhere. You can change it in Settings → Shortcuts.",
  "onboarding.localTitle": "Your data stays here",
  "onboarding.localBody": "Credentials and usage are read from this PC and never uploaded. Pane only talks to the providers you configure.",
